using System;
using Chopper.Core;
using UnityEngine;

namespace Chopper.Trees
{
    [Serializable]
    public struct TreeEntry
    {
        public Vector3 Position;
        public float Yaw;
        public float Scale;
        public TreeSize Size;
        // Neutral for hub trees, otherwise the element of the forest the tree grows in.
        public Element Zone;
        public int ModelIndex;
    }

    // Generated by WorldBuilder from the world seed, the same on every peer. The array index is the stable tree id every peer
    // agrees on, so the network only ever sends ints.
    [CreateAssetMenu(fileName = "SO_TreeDatabase", menuName = "Chopper/Tree Database")]
    public class TreeDatabase : ScriptableObject
    {
        [SerializeField] private GameObject[] _models = Array.Empty<GameObject>();
        [SerializeField] private TreeEntry[] _trees = Array.Empty<TreeEntry>();

        public int Count => _trees.Length;

        public TreeEntry Get(int id) => _trees[id];

        public GameObject GetModel(int modelIndex) => _models[modelIndex];

        public void Bake(GameObject[] models, TreeEntry[] trees)
        {
            _models = models;
            _trees = trees;
        }
    }
}
